---RefreshBoardByContent 根据标题和内容刷新提示板
---@param titleText string 标题文字
---@param data table 队伍数据
function CommonTipsBoardTaskFish:RefreshBoardByContent(taskId, curRating)
	self._taskId = checkNumber(taskId)
	self._curRating = checkNumber(curRating)

	self:FillRewards()
end

function CommonTipsBoardTaskFish:FillRewards()
	local t = FishingUtils.GetFishingAllTaskExtraRewards(self._taskId)

	for k, v in pairs(t) do
		local go = self.Bg.transform:Find("go"..k) 
		if  not go then
			go = CfUtils.InstantiateGo(self.Cell, self.Bg)
			go.name = "go"..k
		end
		KTool.SetActive(go, true)

		local gray = KTool.GetOrAddComponent(go.transform:Find("DescNode").gameObject, typeof(CS.Engine.UI.UIGrayGraphics))
        gray:MarkGray(not (checkNumber(v.rate) == checkNumber(self._curRating)))

        CfUtils.SetUISwitchImage(go.transform:Find("DescNode/TitleNode/Layout/FishGrade/ImgGrade"), checkNumber(v.rate))
		print(FishingUtils.GetFishRareNameByRare(v.rate) == "S" and 2 or 1)
        CfUtils.SetUISwitchImage(go.transform:Find("DescNode/TitleNode/Layout/FishGrade/ImgIcon"), FishingUtils.GetFishRareNameByRare(v.rate) == "S" and 2 or 1)
	
		CfUtils.SetActive(go.transform:Find("DescNode/TextCurrent"))

		local scr = CfUtils.GetLuaScr(go.transform:Find("CommonGoodsList"), CommonGoodsList)
		if scr then
			scr:FreshBaseUI(v.data, false)
		end
	end
end

function CommonTipsBoardTaskFish:SetExcludeDialogs(ids)
	self.excludeDialogs = ids
end



return CommonTipsBoardTaskFish